package com.sobrenaturaldirector.decision.trace;
import java.util.*; import com.sobrenaturaldirector.decision.constraint.ConstraintResult; import com.sobrenaturaldirector.decision.utility.UtilityScoreBreakdown;
public final class CandidateTrace { private final String id; private final boolean eligible, selected; private final List<ConstraintResult> constraints; private final UtilityScoreBreakdown score; public CandidateTrace(String id,boolean eligible,boolean selected,List<ConstraintResult> constraints,UtilityScoreBreakdown score){this.id=id;this.eligible=eligible;this.selected=selected;this.constraints=Collections.unmodifiableList(new ArrayList<ConstraintResult>(constraints));this.score=score;} public String getId(){return id;} public boolean isEligible(){return eligible;} public boolean isSelected(){return selected;} public List<ConstraintResult> getConstraints(){return constraints;} public UtilityScoreBreakdown getScore(){return score;} }
